import React from 'react';

const SortButtons = ({ onSort }) => {
  return (
    <div className="sort-buttons">
      <button onClick={() => onSort('recent')} className="btn-dark active">Recent Updates</button>
      <button onClick={() => onSort('breaking')} className="btn-dark">Failure Impact</button>
      <button onClick={() => onSort('security')} className="btn-dark">Security Impact</button>
      <button onClick={() => onSort('legal')} className="btn-dark">Legal Impact</button>
    </div>
  );
};

export default SortButtons;
